*{box-sizing:border-box} :root{--cream:#f2eee3;--muted:#a9b5aa;--gold:#e4bd70;--green:#123d32;--line:rgba(238,235,216,.18)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071a1a;color:var(--cream);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:radial-gradient(ellipse at 50% 50%,#32604a 0,#163e34 48%,#071a1a 100%)}#scene{position:absolute;inset:0}#scene canvas{display:block;width:100%;height:100%}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(4,17,17,.64) 0%,rgba(4,17,17,.16) 20%,transparent 42%,transparent 66%,rgba(4,17,17,.2) 85%,rgba(4,17,17,.7) 100%),linear-gradient(90deg,rgba(4,17,17,.22),transparent 30%,transparent 70%,rgba(4,17,17,.22))}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:80px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1)}.brand{display:flex;align-items:center;gap:11px;color:var(--cream);text-decoration:none;font-size:12px;line-height:1.04;font-weight:800;letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--gold);color:var(--gold);font-family:'Playfair Display',serif;font-size:22px;font-style:italic;letter-spacing:0;border-radius:50%}.brand-sub{display:block;color:#a6b0a7;font-weight:500;font-size:8px;letter-spacing:2.6px;margin-top:5px}.match-tag{height:31px;display:flex;align-items:center;gap:11px;padding:0 13px;border:1px solid rgba(255,255,255,.18);background:rgba(9,29,25,.35);font-family:'DM Mono',monospace;font-size:9px;letter-spacing:1.25px;color:#deddd2}.match-tag i{height:12px;width:1px;background:rgba(255,255,255,.3);margin:0 3px}.live-dot,.speed-dot{width:6px;height:6px;background:#d2af69;border-radius:50%;box-shadow:0 0 10px #d2af69}.icon-button{width:34px;height:34px;border:1px solid rgba(255,255,255,.2);background:rgba(9,29,25,.3);border-radius:50%;color:#e0d8c6;cursor:pointer;font-size:18px}.scoreboard{position:absolute;z-index:2;top:104px;left:4.2%;display:flex;align-items:flex-start;gap:22px;padding:14px 18px 14px 0;background:linear-gradient(90deg,rgba(5,24,22,.86),rgba(5,24,22,.68));border:1px solid rgba(240,231,207,.15);border-left:2px solid var(--gold);backdrop-filter:blur(8px);box-shadow:0 8px 26px #071a1a38}.score-main{padding:0 2px 0 17px;min-width:195px}.team-line{display:flex;align-items:center;gap:7px}.flag{font-size:14px;filter:saturate(.75)}.team-name{font-size:10px;font-weight:800;letter-spacing:1.9px}.innings-label{margin-left:4px;padding:3px 5px;border:1px solid rgba(228,189,112,.36);color:var(--gold);font-family:'DM Mono',monospace;font-size:7px;letter-spacing:.7px}.score-numbers{display:flex;align-items:baseline;line-height:1;margin:7px 0 5px}.score-numbers strong{font-family:'Playfair Display',serif;font-size:38px;font-weight:600;letter-spacing:-1.6px}.slash{color:#859187;font-family:'Playfair Display',serif;font-size:27px;margin:0 4px}.score-numbers>span:nth-child(3){font-family:'Playfair Display',serif;font-size:29px;color:#d5d9cb}.overs{margin-left:9px;font:10px 'DM Mono',monospace;color:#b1bdb1}.score-meta{font:8px 'DM Mono',monospace;letter-spacing:.5px;color:#abb8aa}.score-meta b{color:#eee9d9;font-weight:500}.meta-sep{margin:0 8px;color:var(--gold)}.score-divider{width:1px;height:82px;background:rgba(238,235,216,.17);margin-top:0}.batter-card{min-width:151px;padding-top:1px}.card-label{font:8px 'DM Mono',monospace;letter-spacing:1.3px;color:#a9b5aa;margin-bottom:10px}.batter-row{height:21px;display:grid;grid-template-columns:9px 1fr 22px 26px;align-items:center;gap:5px;font-size:10px;font-weight:600;letter-spacing:.5px}.batter-row b{font:12px 'DM Mono',monospace;text-align:right}.batter-row small{font:9px 'DM Mono',monospace;color:#b3beb1}.batter-row.muted{color:#9eaaa0;font-weight:500}.on-strike{width:5px;height:5px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px #dbbd76}.on-strike.empty{background:transparent;box-shadow:none}.card-footer{margin-top:9px;padding-top:7px;border-top:1px solid rgba(255,255,255,.11);font:7px 'DM Mono',monospace;letter-spacing:.8px;color:#9eafa2}.card-footer span{font-size:7px;color:var(--gold);margin-right:4px}.facing{margin-left:3px;color:#e3ddca}.bowler-card{min-width:99px;padding-top:1px}.bowler-name{font-family:'Playfair Display',serif;font-size:15px;margin-top:1px}.bowler-stats{display:flex;align-items:center;gap:8px;margin-top:5px;font:12px 'DM Mono',monospace}.bowler-stats small{font-size:8px;color:#aab8ad}.speed{display:flex;align-items:center;gap:5px;margin-top:8px;font:10px 'DM Mono',monospace;color:#e4c378}.speed small{font-size:8px;color:#aab8ad}.speed-dot{width:5px;height:5px}.over-strip{z-index:2;position:absolute;top:108px;right:4.3%;height:43px;display:flex;align-items:center;gap:14px;padding:0 13px;background:rgba(5,24,22,.72);border:1px solid rgba(240,231,207,.14);backdrop-filter:blur(8px)}.over-title{font:8px 'DM Mono',monospace;letter-spacing:1.2px;color:#aab9ad}.ball-track{display:flex;gap:5px}.ball-track i{display:grid;place-items:center;width:17px;height:17px;border-radius:50%;font:8px 'DM Mono',monospace;font-style:normal}.empty-ball{border:1px solid rgba(255,255,255,.31)}.ball-run{background:#c9ad6c;color:#16251c}.ball-four{background:#e8e1c7;color:#14251e}.ball-six{background:#74998c;color:#061a17;border:1px solid #d5dcc5}.ball-wicket{background:#9e5541;color:#fff}.ball-dot{border:1px solid rgba(255,255,255,.5);color:#e2e4d7}.over-summary{font:9px 'DM Mono',monospace;color:#dad6c8;white-space:nowrap}.crosshair{position:absolute;z-index:1;left:50%;top:51%;transform:translate(-50%,-50%);width:32px;height:32px;opacity:.5;pointer-events:none}.crosshair:before,.crosshair:after{content:'';position:absolute;background:rgba(240,229,199,.65)}.crosshair:before{width:1px;height:32px;left:50%}.crosshair:after{height:1px;width:32px;top:50%}.crosshair span{position:absolute;width:3px;height:3px;background:#f1e7cf;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%}.delivery-callout{position:absolute;z-index:2;left:50%;top:63%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;color:#f5e7c9;text-shadow:0 2px 10px #081c16;font:9px 'DM Mono',monospace;letter-spacing:2.1px;opacity:0;transition:opacity .2s;white-space:nowrap}.delivery-callout.visible{opacity:1}.callout-line{width:21px;height:1px;background:var(--gold)}.bottom-ui{z-index:3;position:absolute;bottom:55px;left:4.2%;right:4.2%;display:flex;align-items:flex-end;justify-content:space-between}.left-hint{display:flex;align-items:center;gap:5px;padding-bottom:19px}.keycap,.shot-key{display:grid;place-items:center;width:20px;height:20px;border:1px solid rgba(236,232,212,.34);border-radius:3px;background:rgba(5,24,22,.34);color:#e4dbbf;font:10px 'DM Mono',monospace}.hint-copy{margin-left:5px;color:#c0c6b9;font:8px 'DM Mono',monospace;letter-spacing:1.1px}.shot-select{display:flex;gap:7px}.shot-btn{position:relative;width:91px;height:81px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;background:rgba(6,28,25,.64);border:1px solid rgba(236,232,212,.19);backdrop-filter:blur(8px);cursor:pointer;transition:all .16s}.shot-btn:hover{background:rgba(15,54,43,.83);border-color:#b9a372}.shot-btn.active{background:rgba(19,55,43,.9);border-color:var(--gold);box-shadow:inset 0 0 18px rgba(212,177,106,.1)}.shot-key{position:absolute;top:6px;left:7px;width:15px;height:15px;font-size:8px;border-color:rgba(255,255,255,.24);color:#d8cfb9}.shot-icon{font-size:22px;line-height:22px;color:var(--gold);font-family:serif}.shot-name{font-size:9px;font-weight:800;letter-spacing:1.3px}.shot-btn small{font:7px 'DM Mono',monospace;letter-spacing:1.1px;color:#9eaea2}.swing-button{position:relative;width:142px;height:71px;margin-left:10px;margin-bottom:5px;border:1px solid #e0c47e;background:#c5a666;color:#11241c;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:5px;cursor:pointer;overflow:hidden;box-shadow:0 6px 24px rgba(0,0,0,.2);transition:transform .12s,background .15s}.swing-button:before{content:'';position:absolute;inset:4px;border:1px solid rgba(24,38,27,.28);pointer-events:none}.swing-button:hover{background:#dbc184;transform:translateY(-2px)}.swing-button:active,.swing-button.pressed{transform:scale(.97)}.swing-label{font-size:11px;font-weight:800;letter-spacing:1.5px}.swing-key{font:8px 'DM Mono',monospace;letter-spacing:1px;opacity:.7}.bottom-foot{position:absolute;z-index:3;bottom:0;left:4.2%;right:4.2%;height:39px;border-top:1px solid rgba(241,235,212,.16);display:flex;align-items:center;justify-content:space-between;color:#a7b3a7;font:8px 'DM Mono',monospace;letter-spacing:1.4px}.bottom-foot .foot-center{color:#84978a;letter-spacing:1px}.bottom-foot button{padding:5px 0;border:0;background:none;color:#b6c0b4;cursor:pointer;font:8px 'DM Mono',monospace;letter-spacing:1px}.bottom-foot button:hover{color:var(--gold)}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:rgba(4,18,17,.37);backdrop-filter:blur(2px);transition:opacity .35s,visibility .35s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card{position:relative;width:min(410px,calc(100vw - 36px));padding:36px 39px 28px;background:rgba(7,28,25,.94);border:1px solid rgba(228,189,112,.45);box-shadow:0 20px 70px rgba(0,0,0,.48);text-align:center}.intro-card:before{content:'';position:absolute;inset:6px;border:1px solid rgba(241,233,208,.1);pointer-events:none}.intro-kicker{display:flex;justify-content:center;align-items:center;gap:9px;color:var(--gold);font:8px 'DM Mono',monospace;letter-spacing:2px}.intro-kicker span{width:20px;height:1px;background:#92794a}.intro-card h1{margin:20px 0 12px;font:600 43px/.99 'Playfair Display',serif;letter-spacing:-1.6px}.intro-card h1 em{color:var(--gold);font-weight:600}.intro-card p{margin:0;color:#b7c1b6;font-size:12px;line-height:1.75}.intro-rule{height:1px;background:rgba(239,231,206,.16);margin:21px 0 16px}.intro-details{display:flex;justify-content:center;gap:30px;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#aeb8ac}.intro-details b{display:block;margin-bottom:4px;font:17px 'Playfair Display',serif;color:#f0e8d4}.start-button{position:relative;display:flex;align-items:center;justify-content:center;gap:25px;width:100%;height:46px;margin-top:23px;background:#c8ab6e;border:0;color:#13271e;font-size:10px;font-weight:800;letter-spacing:1.3px;cursor:pointer;transition:background .15s}.start-button:hover{background:#dfc587}.start-button span{font-size:17px}.intro-controls{margin-top:15px;color:#d8d1bd;font:8px 'DM Mono',monospace;letter-spacing:.8px}.intro-controls span{color:#8e9c90;font-size:7px}.intro-controls i{padding:0 5px;color:#957e4e;font-style:normal}.result-card h1{font-size:37px}.result-score{display:flex;align-items:baseline;justify-content:center;gap:10px;margin:22px 0 3px}.result-score strong{font:36px 'Playfair Display',serif;color:var(--gold)}.result-score span{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#a8b5a9}.toast{position:absolute;z-index:4;top:31%;left:50%;transform:translate(-50%,-8px);padding:10px 19px;background:rgba(5,23,20,.82);border:1px solid rgba(228,189,112,.5);color:#f3e7c9;font:9px 'DM Mono',monospace;letter-spacing:2px;opacity:0;pointer-events:none;transition:all .3s}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-tip{display:none}
